INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `description`, `created_at`, `updated_at`) VALUES
('1', 'ĐÔNG ANH FOOD MAP', 'dong-anh-food-map', '🍲', 'Bản đồ ẩm thực Đông Anh - Bún phở, lẩu nướng, quán cafe,...', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('2', 'Stay in Đông Anh', 'stay-in-dong-anh', '🏨', 'Nhà nghỉ, khách sạn, biệt thự, homestay và các khu nghỉ dưỡng tiện nghi tại Đông Anh.', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('3', 'Wellness & Care', 'wellness-care', '🏥', 'Hệ thống cơ sở y tế, phòng khám, chăm sóc sức khỏe và spa thư giãn hàng đầu Đông Anh.', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('4', 'Đặc sản OCOP', 'dong-anh-market', '🛍️', 'Nơi hội tụ các sản phẩm OCOP, quà lưu niệm độc đáo, đặc sản địa phương mang đậm hồn quê Đông Anh.', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('5', 'Smart Education Map', 'smart-education-map', '🏫', 'Hệ thống trường học và cơ sở giáo dục chất lượng cao trên địa bàn huyện Đông Anh.', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('6', 'Hành trình di sản', 'hanh-trinh-di-san', '🏛️', 'Kết nối hành trình khám phá di tích lịch sử và văn hóa thông qua nền tảng Donganh360.vn.', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('7', 'Discover Dong Anh Community & Culture Hub', 'discover-dong-anh-community-culture-hub', '🏛️', 'Khám phá hệ thống thiết chế văn hóa - thể thao Đông Anh: Nhà văn hóa, nhà thi đấu, trung tâm triển lãm, nhà văn hóa thôn và tổ dân phố.', '2026-06-01 10:57:56', '2026-06-01 10:57:56'),
('8', 'Chợ truyền thống', 'traditional-market', '🏪', 'Khám phá các chợ truyền thống nhộn nhịp mang đậm hồn quê Đông Anh.', '2026-07-23 09:26:00', '2026-07-23 09:26:00'),
('9', 'Cơ sở kinh doanh, Doanh nghiệp', 'co-so-kinh-doanh', '🏪', 'Cơ sở kinh doanh độc lập, cửa hàng, siêu thị mini và dịch vụ bán lẻ trên địa bàn.', '2026-08-07 23:14:53', '2026-08-13 09:22:54');
